    {
        $response = $this->promptAuthorize($this->sessionAuthenticated(60, ['pwd', 'otp', 'mfa']))
            ->authorize($this->promptRequest('GET', ['acr_values' => 'urn:lugh:acr:mfa']), new Response(), ['tenant' => 'tenant1']);

